// A adapter une seule fois : ID du document Grist.
const body = $input.first().json.body || {};
return [{
  json: {
    docId: 'cRP1WgZQv7KmwmVrUbuEF8',
    action: (body.action || '').toString(),
    userId: Number(body.userId),
    toPseudo: (body.toPseudo || '').toString().trim(),
    offeredCardId: Number(body.offeredCardId),
    offeredPullId: body.offeredPullId != null ? Number(body.offeredPullId) : null,
    requestedCardId: Number(body.requestedCardId),
    requestedPullId: body.requestedPullId != null ? Number(body.requestedPullId) : null,
    tradeId: Number(body.tradeId),
    originalTradeId: body.originalTradeId != null ? Number(body.originalTradeId) : null,
    accept: body.accept === true || body.accept === 'true'
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const users = $('Create Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const pulls = $('Create Get Pulls').all().map((i) => i.json).filter((r) => r.id != null);
const cards = $('Create Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const trades = $('Create Get Trades').all().map((i) => i.json).filter((r) => r.id != null);

// Une contre-proposition (action='counter') cible automatiquement l'auteur
// de l'echange d'origine (le pseudo cible n'a pas de sens ici, l'echange
// d'origine dit deja qui est l'autre joueur).
const isCounter = cfg.action === 'counter';
let toUserId;
let counterOfTradeId = null;
if (isCounter) {
  const original = trades.find((t) => t.id === cfg.originalTradeId);
  if (!original) return [{ json: { ok: false, error: 'trade_not_found' } }];
  if (refId(original.ToUser) !== cfg.userId) return [{ json: { ok: false, error: 'not_your_trade' } }];
  if (original.Status !== 'pending') return [{ json: { ok: false, error: 'trade_not_pending' } }];
  toUserId = refId(original.FromUser);
  counterOfTradeId = original.id;
} else {
  const toUser = users.find((u) => (u.Pseudo || '').toString().trim().toLowerCase() === cfg.toPseudo.toLowerCase());
  if (!toUser) {
    return [{ json: { ok: false, error: 'user_not_found' } }];
  }
  toUserId = toUser.id;
}
if (toUserId === cfg.userId) {
  return [{ json: { ok: false, error: 'cannot_trade_self' } }];
}

const isGift = !cfg.requestedCardId;
const offeredCard = cards.find((c) => c.id === cfg.offeredCardId);
const requestedCard = isGift ? null : cards.find((c) => c.id === cfg.requestedCardId);
if ((offeredCard && offeredCard.IsPromo) || (requestedCard && requestedCard.IsPromo)) {
  return [{ json: { ok: false, error: 'promo_not_tradeable' } }];
}

// L'utilisateur choisit precisement QUEL exemplaire (numero de serie) de sa
// carte il met dans l'echange, pas juste "une carte au hasard parmi ses
// doublons".
const offeredPull = pulls.find((p) => p.id === cfg.offeredPullId && refId(p.User) === cfg.userId && refId(p.Card) === cfg.offeredCardId);
if (!offeredPull) {
  return [{ json: { ok: false, error: 'card_not_owned' } }];
}

return [{
  json: {
    ok: true,
    docId: cfg.docId,
    fromUserId: cfg.userId,
    toUserId,
    offeredCardId: cfg.offeredCardId,
    offeredPullId: offeredPull.id,
    requestedCardId: isGift ? null : cfg.requestedCardId,
    counterOfTradeId,
    createdAt: Math.floor(Date.now() / 1000)
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const trades = $('List Get Trades').all().map((i) => i.json).filter((r) => r.id != null);
const users = $('List Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const cards = $('List Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const pulls = $('List Get Pulls').all().map((i) => i.json).filter((r) => r.id != null);

const userById = {};
users.forEach((u) => { userById[u.id] = u.Pseudo; });
const cardById = {};
cards.forEach((c) => { cardById[c.id] = c.Name; });
const pullById = {};
pulls.forEach((p) => { pullById[p.id] = p; });

const mine = trades.filter((t) => refId(t.FromUser) === cfg.userId || refId(t.ToUser) === cfg.userId);
const list = mine.map((t) => {
  const requestedId = refId(t.RequestedCard);
  const offeredPull = pullById[refId(t.OfferedPull)];
  const requestedPull = pullById[refId(t.RequestedPull)];
  return {
    tradeId: t.id,
    direction: refId(t.FromUser) === cfg.userId ? 'outgoing' : 'incoming',
    fromPseudo: userById[refId(t.FromUser)] || '?',
    toPseudo: userById[refId(t.ToUser)] || '?',
    offeredCard: { id: refId(t.OfferedCard), name: cardById[refId(t.OfferedCard)] || '?' },
    offeredSerial: offeredPull && offeredPull.SerialNumber != null ? offeredPull.SerialNumber : null,
    requestedCard: requestedId ? { id: requestedId, name: cardById[requestedId] || '?' } : null,
    requestedSerial: requestedPull && requestedPull.SerialNumber != null ? requestedPull.SerialNumber : null,
    status: t.Status,
    createdAt: t.CreatedAt,
    respondedAt: t.RespondedAt || null,
    counterOfTradeId: refId(t.CounterOf) || null
  };
}).sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));

return [{ json: { trades: list } }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const trades = $('Respond Get Trades').all().map((i) => i.json).filter((r) => r.id != null);
const trade = trades.find((t) => t.id === cfg.tradeId);

if (!trade) {
  return [{ json: { ok: false, error: 'trade_not_found' } }];
}
if (refId(trade.ToUser) !== cfg.userId) {
  return [{ json: { ok: false, error: 'not_your_trade' } }];
}
if (trade.Status !== 'pending') {
  return [{ json: { ok: false, error: 'trade_not_pending' } }];
}

const requestedCardId = refId(trade.RequestedCard);
// Contrepartie (hors don) : celui qui accepte choisit LUI-MEME quel
// exemplaire (numero de serie) de la carte demandee il donne en retour.
if (cfg.accept && requestedCardId && !cfg.requestedPullId) {
  return [{ json: { ok: false, error: 'pull_not_chosen' } }];
}

return [{
  json: {
    ok: true,
    docId: cfg.docId,
    tradeId: trade.id,
    fromUserId: refId(trade.FromUser),
    toUserId: refId(trade.ToUser),
    offeredCardId: refId(trade.OfferedCard),
    offeredPullId: refId(trade.OfferedPull),
    requestedCardId,
    requestedPullId: cfg.requestedPullId || null,
    accept: cfg.accept
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const t = $('Find Trade To Respond').first().json;
const pulls = $input.all().map((i) => i.json).filter((r) => r.id != null);
const isGift = !t.requestedCardId;
// L'exemplaire offert a ete fixe des la creation de l'echange (numero de
// serie choisi par le proposeur) : on revalide juste qu'il appartient
// toujours au proposeur (il a pu partir dans un AUTRE echange accepte
// entre-temps).
const pullFrom = pulls.find((p) => p.id === t.offeredPullId && refId(p.User) === t.fromUserId);
// L'exemplaire rendu en retour est choisi maintenant, par celui qui accepte.
const pullTo = isGift ? null : pulls.find((p) => p.id === t.requestedPullId && refId(p.User) === t.toUserId && refId(p.Card) === t.requestedCardId);
if (!pullFrom || (!isGift && !pullTo)) {
  return [{ json: { ok: false, error: 'cards_no_longer_available' } }];
}
return [{
  json: {
    ok: true,
    isGift,
    docId: t.docId,
    tradeId: t.tradeId,
    pullFromId: pullFrom.id,
    pullToId: pullTo ? pullTo.id : null,
    toUserId: t.toUserId,
    fromUserId: t.fromUserId,
    respondedAt: Math.floor(Date.now() / 1000)
  }
}];

const t = $('Pick Pulls To Swap').first().json;
const users = $('Get Users For XP').all().map((i) => i.json).filter((r) => r.id != null);
const fromUser = users.find((u) => u.id === t.fromUserId);
const toUser = users.find((u) => u.id === t.toUserId);

// Niveaux de profil : XP gagnee par les DEUX parties d'un echange accepte,
// +1 booster bonus chacun par niveau franchi.
function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const XP_PER_TRADE = 5;
function computeReward(user) {
  const oldXp = (user && user.XP) || 0;
  const newXp = oldXp + XP_PER_TRADE;
  const levelsGained = levelForXp(newXp) - levelForXp(oldXp);
  const newBoosterCount = ((user && user.BoosterCount) || 0) + levelsGained;
  return { newXp, newBoosterCount };
}
const fromReward = computeReward(fromUser);
const toReward = computeReward(toUser);

return [{ json: {
  docId: t.docId,
  fromUserId: t.fromUserId,
  toUserId: t.toUserId,
  fromNewXp: fromReward.newXp,
  fromNewBoosterCount: fromReward.newBoosterCount,
  toNewXp: toReward.newXp,
  toNewBoosterCount: toReward.newBoosterCount
} }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const trades = $('Cancel Get Trades').all().map((i) => i.json).filter((r) => r.id != null);
const trade = trades.find((t) => t.id === cfg.tradeId);

if (!trade) {
  return [{ json: { ok: false, error: 'trade_not_found' } }];
}
if (refId(trade.FromUser) !== cfg.userId) {
  return [{ json: { ok: false, error: 'not_your_trade' } }];
}
if (trade.Status !== 'pending') {
  return [{ json: { ok: false, error: 'trade_not_pending' } }];
}
return [{ json: { ok: true, docId: cfg.docId, tradeId: trade.id } }];

